#include <Wire.h>
#include <LiquidCrystal_I2C.h>

// Ultrasonic Distance Meter with LCD
// Displays live HC-SR04 distance readings on a 16x2 I2C LCD.

const int TRIG_PIN = 9;
const int ECHO_PIN = 10;

LiquidCrystal_I2C lcd(0x27, 16, 2); // change 0x27 if your backpack uses a different address

void setup() {
  pinMode(TRIG_PIN, OUTPUT);
  pinMode(ECHO_PIN, INPUT);

  lcd.init();
  lcd.backlight();
  lcd.setCursor(0, 0);
  lcd.print("Distance Meter");
  delay(1000);
}

void loop() {
  long distance = readDistanceCm();

  lcd.clear();
  lcd.setCursor(0, 0);
  lcd.print("Distance:");
  lcd.setCursor(0, 1);
  lcd.print(distance);
  lcd.print(" cm");

  delay(300); // slow the refresh so the display is readable, not flickering
}

long readDistanceCm() {
  digitalWrite(TRIG_PIN, LOW);
  delayMicroseconds(2);
  digitalWrite(TRIG_PIN, HIGH);
  delayMicroseconds(10);
  digitalWrite(TRIG_PIN, LOW);

  long duration = pulseIn(ECHO_PIN, HIGH, 30000);
  if (duration == 0) return -1; // out of range / no echo
  return duration / 58;
}
